import type { RequestHandler } from 'express';
import { createClient } from 'redis';

const redis = createClient({ url: process.env.REDIS_URL });
redis.connect().catch(console.error);

const LIMIT = 100;          // requests
const WINDOW = 60;          // seconds

export const rateLimit: RequestHandler = async (req, res, next) => {
  const key = `rl:${req.ip}`;
  const n = await redis.incr(key);
  if (n === 1) await redis.expire(key, WINDOW);
  res.setHeader('X-RateLimit-Limit', LIMIT);
  res.setHeader('X-RateLimit-Remaining', Math.max(0, LIMIT - n));
  if (n > LIMIT) return res.status(429).json({ error: 'rate limit exceeded' });
  next();
};

